import assert from 'node:assert/strict';
import test from 'node:test';

import { hex } from '@scure/base';
import { Transaction } from '@scure/btc-signer/transaction.js';

import { broadcastPearlTransaction } from '../src/pearl-indexer.ts';
import { openPearlWallet, validatePearlAddress } from '../src/pearl-keys.ts';
import { defaultPearlNetwork, pearlNetworks } from '../src/pearl-network.ts';
import {
  isPaymentIndexed,
  loadWalletSnapshot,
  outpointId,
  preparePayment,
  verifyInputsStillAvailable,
} from '../src/testnet-wallet.ts';

// Public Oyster wallet vectors generated by PocketPRL.
// https://github.com/pocketprl/pocketprl/blob/be117e90180648fca2e615df3c107bb9c58673e5/app/src/test/resources/pearl_vectors.json
const phrase = 'abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon abandon about';
const mainnet = {
  network: 'mainnet',
  address: 'prl1pr6yuq8u2r95wjzzgpdy8cpnncpl7l8zgy6x5q0367pnc53s2famqg7pt74',
  scriptHex: '51201e89c01f8a1968e908480b487c0673c07fef9c48268d403e3af0678a460a4f76',
  miningAddress: 'prl1pyx3nlscz8rvsxqhcjtyqt2g5szuk9ss7m5saszu3afwwhvn9zp2sz62rhm',
  miningScriptHex: '512021a33fc30238d90302f892c805a91480b962c21edd21d80b91ea5cebb2651055',
};
const testnetAddress = 'tprl1p8wpt9v4frpf3tkn0srd97pksgsxc5hs52lafxwru9kgeephvs7rqm5v93u';
const externalAddress = 'prl1p0nmh8c37r797n8hh9eltzm69f27thq0camd2j28wq4cygs6e2n9sd5wceq';
const apiBase = pearlNetworks.mainnet.explorer + '/api/v2';
const tip = {
  backend: { chain: 'mainnet' },
  blockbook: { coin: 'Pearl', decimals: 8, bestHeight: 153000, inSync: true, inSyncMempool: true },
};

function addressHistoryPath(address) {
  return `/address/${address}?details=txslight&page=1&pageSize=15`;
}

function utxoPath(address) {
  return `/utxo/${address}?confirmed=false`;
}

function mockReadOnlyIndexer(context, responses) {
  return context.mock.method(globalThis, 'fetch', async (url, options) => {
    assert.ok(url.startsWith(apiBase));
    assert.equal(options.method, 'GET');
    const path = url.slice(apiBase.length);
    assert.ok(Object.hasOwn(responses, path), 'Unexpected request ' + path);
    return Response.json(responses[path]);
  });
}

function previousOutput(address, scriptHex, amount, confirmations, coinbase = false) {
  const transaction = new Transaction({ version: 1 });
  transaction.addOutput({ amount: BigInt(amount), script: hex.decode(scriptHex) });
  transaction.addInput({
    txid: (coinbase ? '0' : 'a').repeat(64),
    index: coinbase ? 0xffffffff : 0,
    finalScriptSig: coinbase ? hex.decode('020603') : undefined,
  });
  return {
    utxo: { txid: transaction.id, vout: 0, confirmations, height: 153001 - confirmations, value: String(amount) },
    details: {
      txid: transaction.id,
      hex: transaction.hex,
      confirmations,
      vin: [coinbase ? { coinbase: '020603' } : { txid: 'a'.repeat(64) }],
      vout: [{ n: 0, value: String(amount), hex: scriptHex, addresses: [address] }],
    },
  };
}

test('mainnet and Testnet2 restore their own addresses from the public Oyster phrase', () => {
  assert.equal(defaultPearlNetwork, 'mainnet');
  const initial = openPearlWallet(phrase, 'mainnet');
  const restored = openPearlWallet(phrase, 'mainnet');
  const testnet = openPearlWallet(phrase, 'testnet2');
  try {
    assert.equal(initial.address(), mainnet.address);
    assert.equal(initial.scriptHex(), mainnet.scriptHex);
    assert.equal(initial.address(0, 1), mainnet.miningAddress);
    assert.equal(initial.scriptHex(0, 1), mainnet.miningScriptHex);
    assert.equal(restored.address(), initial.address());
    assert.equal(restored.address(0, 1), initial.address(0, 1));
    assert.equal(testnet.address(), testnetAddress);
    assert.equal(validatePearlAddress(testnetAddress, 'mainnet'), null);
    assert.equal(validatePearlAddress(mainnet.address, 'testnet2'), null);
  } finally {
    initial.close();
    restored.close();
    testnet.close();
  }
});

test('mainnet balance sums both addresses, counts shared activity once and excludes immature coinbase', async context => {
  const normal = previousOutput(mainnet.address, mainnet.scriptHex, 200_000, 102);
  const immature = previousOutput(mainnet.miningAddress, mainnet.miningScriptHex, 300_000, 99, true);
  const sharedTransaction = {
    txid: 'ab'.repeat(32),
    vin: [{ addresses: [externalAddress], value: '500500' }],
    vout: [
      { addresses: [mainnet.address], value: '200000' },
      { addresses: [mainnet.miningAddress], value: '300000' },
    ],
    fees: '500',
    confirmations: 1,
  };
  mockReadOnlyIndexer(context, {
    '': tip,
    [addressHistoryPath(mainnet.address)]: {
      address: mainnet.address, balance: '200000', unconfirmedBalance: '0', transactions: [sharedTransaction],
    },
    [addressHistoryPath(mainnet.miningAddress)]: {
      address: mainnet.miningAddress, balance: '300000', unconfirmedBalance: '0', transactions: [sharedTransaction],
    },
    [utxoPath(mainnet.address)]: [normal.utxo],
    [utxoPath(mainnet.miningAddress)]: [immature.utxo],
    ['/tx/' + immature.utxo.txid]: immature.details,
  });

  const snapshot = await loadWalletSnapshot(mainnet);
  assert.equal(snapshot.balanceGrains, 500_000);
  assert.equal(snapshot.spendableGrains, 200_000);
  assert.equal(snapshot.activity.length, 1);
  assert.equal(snapshot.activity[0].amountGrains, 500_000);
  assert.equal(snapshot.activity[0].kind, 'receive');
  assert.equal(snapshot.activity[0].recipient, externalAddress);
});

test('mainnet review and offline signing use both address paths and return change to the receive address', async context => {
  const normal = previousOutput(mainnet.address, mainnet.scriptHex, 600_000, 101);
  const mining = previousOutput(mainnet.miningAddress, mainnet.miningScriptHex, 900_000, 100, true);
  const responses = {
    '': tip,
    '/estimatefee/2': { result: '0.0131972' },
    [utxoPath(mainnet.address)]: [normal.utxo],
    [utxoPath(mainnet.miningAddress)]: [mining.utxo],
    ['/tx/' + normal.utxo.txid]: normal.details,
    ['/tx/' + mining.utxo.txid]: mining.details,
  };
  const request = mockReadOnlyIndexer(context, responses);

  await assert.rejects(preparePayment(mainnet, testnetAddress, '0.01'), /Mainnet address/);
  await assert.rejects(preparePayment(mainnet, mainnet.miningAddress, '0.01'), /another Mainnet wallet/);
  assert.equal(request.mock.callCount(), 0);

  const plan = await preparePayment(mainnet, externalAddress, '0.01');
  assert.equal(plan.amountGrains, 1_000_000);
  assert.equal(plan.feeGrains, 279_840);
  assert.equal(plan.changeGrains, 220_160);
  assert.deepEqual(plan.inputs.map(input => input.index), [1, 0]);
  await verifyInputsStillAvailable(plan);

  const wallet = openPearlWallet(phrase, 'mainnet');
  try {
    const signed = wallet.signPayment({ ...plan, entropy: new Uint8Array(32).fill(3) });
    const transaction = Transaction.fromRaw(hex.decode(signed.hex));
    assert.equal(transaction.inputsLength, 2);
    assert.equal(transaction.getOutput(0).amount, 1_000_000n);
    assert.equal(transaction.getOutput(1).amount, 220_160n);
    assert.equal(hex.encode(transaction.getOutput(1).script), mainnet.scriptHex);

    const payment = { ...signed, address: mainnet.address, inputIds: plan.inputs.map(outpointId) };
    responses['/tx/' + signed.txid] = {
      txid: signed.txid, hex: signed.hex, confirmations: 0, vin: [], vout: [],
    };
    responses[utxoPath(mainnet.address)] = [];
    assert.equal(await isPaymentIndexed(payment, mainnet), false);
    responses[utxoPath(mainnet.miningAddress)] = [];
    assert.equal(await isPaymentIndexed(payment, mainnet), true);
    await assert.rejects(verifyInputsStillAvailable(plan), /spendable coins changed/);
  } finally {
    wallet.close();
  }
});

test('mainnet broadcast refuses a cross-network chain identity before relaying bytes', async context => {
  const request = mockReadOnlyIndexer(context, { '': { ...tip, backend: { chain: 'testnet2' } } });
  await assert.rejects(broadcastPearlTransaction('mainnet', 'baba', 'a'.repeat(64)), /Mainnet/);
  assert.equal(request.mock.callCount(), 1);
});

import { liveFeedUrl, parseLiveMessage, reconnectDelay } from '../src/live-feed.ts';

test('maps networks to their Blockbook websocket and reads live events', () => {
  assert.equal(liveFeedUrl('mainnet'), 'wss://blockbook.pearlnetwork.net/websocket');
  assert.equal(liveFeedUrl('testnet2'), 'wss://blockbook.testnet2.pearlnetwork.net/websocket');
  const mine = 'prl1pmine';
  assert.deepEqual(parseLiveMessage('{"id":"block","data":{"height":148264,"hash":"ab"}}', [mine]), { kind: 'block', height: 148264 });
  assert.deepEqual(parseLiveMessage(JSON.stringify({ id: 'addresses', data: { address: mine, tx: { txid: 'cd' } } }), [mine]),
    { kind: 'address', address: mine, txid: 'cd' });
  assert.equal(parseLiveMessage(JSON.stringify({ id: 'addresses', data: { address: 'prl1pother', tx: {} } }), [mine]), null);
  assert.equal(parseLiveMessage('{"id":"block","data":{"subscribed":true}}', [mine]), null);
  assert.equal(parseLiveMessage('{"id":"x","data":{"error":{"message":"no"}}}', [mine]), null);
  assert.equal(parseLiveMessage('not json', [mine]), null);
  assert.deepEqual([0, 1, 2, 5, 10].map(reconnectDelay), [1000, 2000, 4000, 30000, 30000]);
});

test('fee speed picks the matching Blockbook estimate target', async context => {
  const normal = previousOutput(mainnet.address, mainnet.scriptHex, 600_000, 101);
  const responses = {
    '': tip,
    '/estimatefee/1': { result: '0.02' },
    '/estimatefee/2': { result: '0.0131972' },
    '/estimatefee/6': { result: '0.00001' },
    [utxoPath(mainnet.address)]: [normal.utxo],
    [utxoPath(mainnet.miningAddress)]: [],
    ['/tx/' + normal.utxo.txid]: normal.details,
  };
  const request = mockReadOnlyIndexer(context, responses);
  const fast = await preparePayment(mainnet, externalAddress, '0.001', undefined, 'fast');
  const usual = await preparePayment(mainnet, externalAddress, '0.001');
  const slow = await preparePayment(mainnet, externalAddress, '0.001', undefined, 'slow');
  const feePaths = request.mock.calls.map(call => String(call.arguments[0])).filter(url => url.includes('/estimatefee/'));
  assert.deepEqual(feePaths.map(url => url.slice(url.indexOf('/estimatefee/'))), ['/estimatefee/1', '/estimatefee/2', '/estimatefee/6']);
  assert.ok(fast.feeGrains > usual.feeGrains && usual.feeGrains > slow.feeGrains);
  assert.ok(slow.feeGrains > 0);
});

test('coin control spends only the chosen pearls', async context => {
  const large = previousOutput(mainnet.address, mainnet.scriptHex, 5_000_000, 120);
  const small = previousOutput(mainnet.miningAddress, mainnet.miningScriptHex, 2_000_000, 130);
  mockReadOnlyIndexer(context, {
    '': tip,
    '/estimatefee/2': { result: '0.00001' },
    [utxoPath(mainnet.address)]: [large.utxo],
    [utxoPath(mainnet.miningAddress)]: [small.utxo],
    ['/tx/' + large.utxo.txid]: large.details,
    ['/tx/' + small.utxo.txid]: small.details,
  });
  const automatic = await preparePayment(mainnet, externalAddress, '0.01');
  assert.deepEqual(automatic.inputs.map(outpointId), [outpointId(large.utxo)]);
  const chosen = await preparePayment(mainnet, externalAddress, '0.01', undefined, 'normal', [outpointId(small.utxo)]);
  assert.deepEqual(chosen.inputs.map(outpointId), [outpointId(small.utxo)]);
  await assert.rejects(preparePayment(mainnet, externalAddress, '0.03', undefined, 'normal', [outpointId(small.utxo)]), /chosen pearls cannot cover/);
  await assert.rejects(preparePayment(mainnet, externalAddress, '0.01', undefined, 'normal', ['f'.repeat(64) + ':0']), /no longer spendable/);
});

import { currentReceiveAddress, discoverReceiveIndex, walletAddresses } from '../src/testnet-wallet.ts';

test('fresh receive addresses are tracked and the restore scan honours the gap limit', async context => {
  const wallet = openPearlWallet(phrase, 'mainnet');
  const identity = { ...mainnet, watchKey: wallet.watchKey(), receiveIndex: 3 };
  const used = new Set([wallet.address(0, 4), wallet.address(0, 9)]);
  const checked = [];
  try {
    assert.deepEqual(walletAddresses(identity).map(owned => owned.index), [0, 1, 2, 3]);
    assert.equal(currentReceiveAddress(identity), wallet.address(0, 3));
    assert.equal(currentReceiveAddress({ ...identity, receiveIndex: 0 }), mainnet.address);
    context.mock.method(globalThis, 'fetch', async url => {
      const address = decodeURIComponent(String(url).split('/address/')[1].split('?')[0]);
      checked.push(address);
      return Response.json({ address, txs: used.has(address) ? 2 : 0 });
    });
    assert.equal(await discoverReceiveIndex(identity), 9);
    // Indices 2..29 in batches of five: the scan stops once 20 in a row after 9 are unused.
    assert.equal(checked.length, 30);
    assert.equal(await discoverReceiveIndex({ ...identity, watchKey: undefined }), 0);
  } finally {
    wallet.close();
  }
});

import { supportAddress, supportTipGrains } from '../src/support.ts';

test('an optional 0.5% Pearlet tip is a separate output, never on dust or a tip to Pearlet itself', async context => {
  assert.equal(supportTipGrains(1_000_000), 5_000);
  assert.equal(supportTipGrains(60_000), 0);
  const normal = previousOutput(mainnet.address, mainnet.scriptHex, 5_000_000, 120);
  mockReadOnlyIndexer(context, {
    '': tip,
    '/estimatefee/2': { result: '0.00001' },
    [utxoPath(mainnet.address)]: [normal.utxo],
    [utxoPath(mainnet.miningAddress)]: [],
    ['/tx/' + normal.utxo.txid]: normal.details,
  });
  const without = await preparePayment(mainnet, externalAddress, '0.01');
  assert.equal(without.tip, undefined);
  const withTip = await preparePayment(mainnet, externalAddress, '0.01', undefined, 'normal', undefined, true);
  assert.deepEqual(withTip.tip, { address: supportAddress, amountGrains: 5_000 });
  assert.equal(withTip.changeGrains, 5_000_000 - 1_000_000 - 5_000 - withTip.feeGrains);
  assert.ok(withTip.feeGrains > without.feeGrains);
  const toPearlet = await preparePayment(mainnet, supportAddress, '0.01', undefined, 'normal', undefined, true);
  assert.equal(toPearlet.tip, undefined);
  const wallet = openPearlWallet(phrase, 'mainnet');
  try {
    const signed = wallet.signPayment({ ...withTip, entropy: new Uint8Array(32).fill(4) });
    const transaction = Transaction.fromRaw(hex.decode(signed.hex));
    assert.equal(transaction.getOutput(1).amount, 5_000n);
    assert.equal(hex.encode(transaction.getOutput(2).script), mainnet.scriptHex);
  } finally {
    wallet.close();
  }
});
